async function myId(){return API.session?API.session.uid:null}
async function statHit(kind,tool){if(kind=="open")API.event("open",tool);return true}
function curCountry(){return MULTI?multiNames.join("+"):(findC($("cin").value)||$("cin").value||"")}
API.download=async function(tool,country){
  try{const r=await this.j("POST","/download",{tool,country});if(this.me&&this.me.quota)this.me.quota.used++;if(r.gifts&&r.gifts.length)setTimeout(()=>{try{toast("🎁 "+L_("קיבלתם","You got")+": "+r.gifts.join(" · "))}catch(e){}},1500);return{ok:true,remaining:r.remaining}}
  catch(e){const s=e.status;
    if(s==401){authOpen("login");return{ok:false,msg:L_("כדי להוריד צריך להתחבר","Sign in to download")}}
    if(s==429)return{ok:false,msg:L_("הגעת למכסת ההורדות היומית ("+((e.data&&e.data.limit)||"")+"). אפשר לנסות שוב מחר.","You've reached the daily download limit ("+((e.data&&e.data.limit)||"")+"). Try again tomorrow.")};
    if(s==403&&e.data&&e.data.code=="early")return{ok:false,msg:L_("הכלי הזה פתוח כרגע רק למשתמשים עם גישה מוקדמת.","This tool is currently open to early-access users only.")};
    if(s==403&&e.data&&e.data.code=="verify")return{ok:false,msg:L_("כדי להוריד צריך לאמת את כתובת המייל – בדקו את תיבת הדואר.","Verify your email to download – check your inbox.")};
    if(s==403)return{ok:false,msg:L_("החשבון חסום. פנו למנהל האתר.","Your account is blocked. Contact the site owner.")};
    if(s==503&&e.data&&e.data.code=="blocked")return{ok:false,msg:e.message};
    if(s==503)return{ok:false,msg:L_("האתר בתחזוקה כרגע.","The site is under maintenance.")};
    return{ok:false,msg:L_("ההורדה נכשלה, נסו שוב.","Download failed, please try again.")}}};
function continueDownload(){let t=0;try{t=+localStorage.getItem("trip3d_dl")||0;localStorage.removeItem("trip3d_dl")}catch(e){}if(t&&Date.now()-t<30*60e3&&API.session)setTimeout(()=>{$("home").style.display="none";$("intro").style.display="none";$("dl").click()},400)}
function resumeWork(){try{const raw=localStorage.getItem("trip3d_p");if(!raw)return false;putProj(JSON.parse(raw));$("home").style.display="none";$("intro").style.display="none";return true}catch(e){return false}}
window.quotaHtml=()=>{const q=API.me&&API.me.quota;if(!API.session||!q)return"";const l=q.limit;return `<p class="hint">${L_("הורדות היום","Downloads today")}: <b>${q.used||0}</b>${l>0?" / "+l+" · "+L_("נשארו","left")+" <b>"+Math.max(0,l-(q.used||0))+"</b>":" ("+L_("ללא הגבלה","unlimited")+")"}${q.credits?" · 🎁 +"+q.credits+" "+L_("הורדות נוספות","bonus downloads"):""}${(q.perks||[]).some(p=>p.type=="daily")?" · 🎁 "+L_("הטבה פעילה","active perk"):""}</p>`};
